//! Contains search entity models

use thiserror::Error;

use crate::domain::models::{funder::Funder as FunderDetails, parliament_member::ParliamentMember};

const MAX_STRICTNESS: f32 = 1_f32;
const MIN_STRICTNESS: f32 = 0_f32;
const MIN_ENTRIES: u8 = 1;

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity kind
pub enum Entity {
    /// Company entity
    Funder(FunderDetails),
    /// Member entitiy
    ParliamentMember(ParliamentMember),
}

impl Entity {
    #[must_use]
    /// Entity name
    pub fn name(&self) -> &str {
        match self {
            Self::Funder(kind) => kind.name(),
            Self::ParliamentMember(mp) => mp.name(),
        }
    }

    #[must_use]
    /// Entity kind
    pub const fn kind(&self) -> &str {
        match self {
            Self::Funder(_) => "Funder",
            Self::ParliamentMember(_) => "MP",
        }
    }

    #[must_use]
    /// Funder kind
    pub fn funder_kind(&self) -> Option<&str> {
        match self {
            Self::Funder(kind) => Some(kind.kind()),
            Self::ParliamentMember(_) => None,
        }
    }
}

impl From<&ParliamentMember> for Entity {
    fn from(value: &ParliamentMember) -> Self {
        Self::ParliamentMember(value.clone())
    }
}

impl From<&FunderDetails> for Entity {
    fn from(value: &FunderDetails) -> Self {
        Self::Funder(value.clone())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity name
pub struct EntityName(String);

#[derive(Clone, Debug, PartialEq)]
/// Data required to search entities
pub struct EntitySearchRequest {
    term: String,
    strictness: f32,
    max_entries: u8,
}

impl EntitySearchRequest {
    #[must_use]
    /// Search term
    pub const fn term(&self) -> &str {
        self.term.as_str()
    }

    #[must_use]
    /// Search strictness
    pub const fn strictness(&self) -> f32 {
        self.strictness
    }

    #[must_use]
    /// Max result set
    pub const fn max_entries(&self) -> u8 {
        self.max_entries
    }
}

impl EntitySearchRequest {
    /// Creates new instance with [`MAX_STRICTNESS`]
    ///
    /// # Errors
    /// - See [`Self::new_with_strictness`]
    pub fn new_strict(term: String, max_entries: u8) -> Result<Self, EntitySearchError> {
        Self::new_with_strictness(term, max_entries, MAX_STRICTNESS)
    }
    /// Creates new instance with variable strictness
    ///
    /// # Errors
    /// - Term too short
    /// - Too few entries
    /// - Invalid strictness
    pub fn new_with_strictness(
        term: String,
        max_entries: u8,
        strictness: f32,
    ) -> Result<Self, EntitySearchError> {
        // It will be a u8
        #[allow(clippy::cast_possible_truncation)]
        if term.trim().len() < 3 {
            return Err(EntitySearchError::InvalidTerm(term.trim().len() as u8));
        }
        if max_entries < MIN_ENTRIES {
            return Err(EntitySearchError::TooFewEntries);
        }
        if strictness < MIN_STRICTNESS || strictness > MAX_STRICTNESS {
            return Err(EntitySearchError::InvalidStrictness(strictness));
        }
        Ok(Self {
            term,
            strictness,
            max_entries,
        })
    }
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntitySearchError {
    /// Unexpected runtime errors, usually from the database
    #[error("unexpected error occurred: {0}")]
    UnexpectedError(String),

    /// Term too short for generating valid search results
    #[error("term must be at last three characters long; received {0}")]
    InvalidTerm(u8),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    TooFewEntries,

    /// Invalid strictness value
    #[error("strictness must be between {MIN_STRICTNESS} and {MAX_STRICTNESS}; get {0}")]
    InvalidStrictness(f32),
}
use thiserror::Error;

use crate::domain::models::{
    entity_search::EntitySearchRequest, funder::Funder, search_similarity::SearchSimilarity,
};

/// Allows users to search the databse using free text.
pub trait FunderRepo: Clone + Send + Sync + 'static {
    /// Returns entities based on free text search
    fn get_funders_by_text_search_score(
        &self,
        term: &EntitySearchRequest,
    ) -> impl Future<Output = Result<Vec<(Funder, SearchSimilarity)>, FunderRepoError>> + Send;
}

/// Errors that can occur when interacting with the repo
#[derive(Error, Debug)]
pub enum FunderRepoError {
    /// Generic error from the database
    #[error("unable to get search results due to {0}")]
    DatabaseError(String),
}
//! Concrete implementation of the repository

use crate::{
    domain::{
        models::{
            declaration_ingestion::MemberAsId, entity_search::EntitySearchRequest,
            parliament_member::ParliamentMember, search_similarity::SearchSimilarity,
        },
        repositories::parliament_member_repository::{
            ParliamentMemberRepo, ParliamentMemberRepoError,
        },
    },
    outbound::postgres::ExposedDatabase,
};

impl ParliamentMemberRepo for ExposedDatabase {
    async fn get_stored_member_ids(&self) -> Result<Vec<MemberAsId>, ParliamentMemberRepoError> {
        sqlx::query!(
            "
            SELECT id, parliament_member_id
            FROM exposed.members
            ORDER BY parliament_member_id, id
            "
        )
        .fetch_all(self.pool())
        .await
        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?
        .into_iter()
        .map(|row| {
            let parliament_id = u32::try_from(row.parliament_member_id)
                .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
            MemberAsId::new(row.id, parliament_id)
                .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))
        })
        .collect()
    }

    #[allow(clippy::cast_sign_loss)]
    async fn get_members_by_text_search_score(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(ParliamentMember, SearchSimilarity)>, ParliamentMemberRepoError> {
        sqlx::query!(
            "
            SELECT  
                m.name,
                m.parliament_member_id,
                m.party_name,
                m.party_id,
                m.latest_membership_from as constituency,
                 word_similarity($1, m.name) as similarity_score,
                row_number() OVER (ORDER BY word_similarity($1, m.name) DESC) as rank
            FROM members m
            WHERE word_similarity($1, m.name) >= $2
            ORDER BY similarity_score DESC
            ",
            req.term(),
            req.strictness()
        )
        .fetch_all(self.pool())
        .await
        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?
        .into_iter()
        .take_while(|r| {
            r.rank.unwrap_or_else(|| i64::from(req.max_entries() + 1))
                <= i64::from(req.max_entries())
        })
        .map(|r| {
            let member = ParliamentMember::new(
                r.name,
                r.parliament_member_id as u32,
                r.party_name,
                r.party_id as u32,
                r.constituency,
            );
            let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
            Ok((member, score))
        })
        .collect()
    }

    async fn upsert_members(
        &self,
        members: &[ParliamentMember],
    ) -> Result<(), ParliamentMemberRepoError> {
        let mut tx = self
            .pool()
            .begin()
            .await
            .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;

        for m in members {
            let res = sqlx::query!(
                "
            INSERT INTO 
                exposed.members (
                    parliament_member_id, 
                    name, 
                    party_id,
                    party_name,
                    latest_house,
                    latest_membership_from,
                    is_current_commons
           ) 
            VALUES ($1,$2,$3,$4,1,$5,true)
           ON CONFLICT (parliament_member_id) DO UPDATE SET
               name = EXCLUDED.name, party_id = EXCLUDED.party_id,
               party_name = EXCLUDED.party_name, latest_house = EXCLUDED.latest_house,
               latest_membership_from = EXCLUDED.latest_membership_from,
               is_current_commons = EXCLUDED.is_current_commons
           RETURNING id
            ",
                m.member_id().cast_signed(),
                m.name(),
                m.party_id().cast_signed(),
                m.party_name(),
                m.constituency()
            )
            .fetch_one(&mut *tx)
            .await;

            if let Err(e) = res {
                println!("{e}");
            }
        }
        tx.commit()
            .await
            .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
        Ok(())
    }
}

